entries[285638] = { ["name"] = "N'Zoths Geschenk: Hysterie", ["text"] = "100 Energie\nWirken in 2 sek.\nBei Erreichen der vollen Energie verursacht Uu'nat eine Explosion auf dem Boden und fügt allen Spielercharakteren 11995 Schattenschaden zu.\n\n' N'Zoths Geschenk: Hysterie ' heilt alle Diener von N'Zoth um 100% Gesundheit und gewährt ihnen dauerhaft 100% Tempo sowie Bewegungsgeschwindigkeit." }
entries[285639] = { ["name"] = "Vantusrune: Schlacht von Dazar'alor", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Ultramarinblaue Tinte (30), Grünliche Tinte (10)\nErschafft eine Vantusrune: Schlacht von Dazar'alor.\nBeute von:\nSchlacht von Dazar'alor\n\nSchatz:\nSchlacht von Dazar'alor\n\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses der Schlacht von Dazar'alor ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\n45" }
entries[285640] = { ["name"] = "Vantusrune: Schlacht von Dazar'alor", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Ultramarinblaue Tinte (28), Grünliche Tinte (8)\nVerringert die erforderlichen Materialien zur Herstellung einer Vantusrune: Schlacht von Dazar'alor.\nBeute von:\nSchlacht von Dazar'alor\n\nSchatz:\nSchlacht von Dazar'alor\n\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses der Schlacht von Dazar'alor ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\n45" }
entries[285641] = { ["name"] = "Vantusrune: Schlacht von Dazar'alor", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Ultramarinblaue Tinte (25), Grünliche Tinte (6)\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer Vantusrune: Schlacht von Dazar'alor.\nBeute von:\nSchlacht von Dazar'alor\n\nSchatz:\nSchlacht von Dazar'alor\n\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses der Schlacht von Dazar'alor ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\n45" }
